// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.33;

/// @title MetricOmmPoolDeployer
/// @notice Deploys pools from full initcode passed in calldata, only callable by the factory
contract MetricOmmPoolDeployer {
  /// @notice The factory address that is allowed to deploy pools
  address public immutable factory;

  /// @notice Thrown when caller is not the factory
  error OnlyFactory();

  /// @notice Thrown when CREATE2 deployment fails
  error DeployFailed();

  /// @param _factory The factory address
  constructor(address _factory) {
    factory = _factory;
  }

  /// @notice Restricts function to factory only
  modifier onlyFactory() {
    if (msg.sender != factory) revert OnlyFactory();
    _;
  }

  /// @notice Deploys a new MetricOmmPool
  /// @dev Only callable by the factory
  /// @param salt CREATE2 salt
  /// @param initCode Full initcode (creation bytecode + ABI-encoded constructor args)
  /// @return pool The deployed pool address
  function deploy(bytes32 salt, bytes calldata initCode) external onlyFactory returns (address pool) {
    bytes memory code = initCode;
    assembly {
      pool := create2(0, add(code, 32), mload(code), salt)
    }
    if (pool == address(0)) revert DeployFailed();
  }
}

