pragma solidity ^0.8.33;

import "./MetricOmmPoolDeployer.sol";
import "@openzeppelin/contracts/access/Ownable2Step.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/// @title MetricOmmPoolFactory
/// @notice Factory for deploying MetricOmmPool instances via PoolDeployer
/// @dev Implements Ownable2Step for secure ownership transfer
contract MetricOmmPoolFactory is Ownable2Step {
  using SafeERC20 for IERC20;

  // ============ Structs ============

  /// @notice Parameters for creating a new pool
  struct PoolParameters {
    bytes poolCreationCode;
    address token0;
    address token1;
    address priceProvider;
    address admin;
    uint104 initialToken0DensityPerLiquidityE18;
    uint104 initialToken1DensityPerLiquidityE18;
    uint104 minimalMintableLiquidity;
    bool reportSwapToPriceProvider;
    uint256 maxDriftE8;
    uint256 driftDecayPerSecondE8;
    uint24 adminFee;
    address adminFeeDestination;
    int32 curBinDistFromProvidedPriceE6;
    uint256[] nonNegativeBinDataArray;
    uint256[] negativeBinDataArray;
    bytes32 salt;
  }

  // ============ Events ============

  /// @notice Emitted when a new pool is created
  event PoolCreated(
    address indexed token0, address indexed token1, address indexed priceProvider, address pool, bytes32 poolKey
  );

  /// @notice Emitted when the default protocol fee is updated
  event protocolFeeUpdated(uint24 oldFee, uint24 newFee);

  /// @notice Emitted when tokens are collected from the factory
  event TokensCollected(address indexed token, address indexed to, uint256 amount);

  /// @notice Emitted when the pool deployer is set
  event PoolDeployerSet(address indexed poolDeployer);

  // ============ Errors ============

  /// @notice Thrown when token0 >= token1
  error InvalidTokenOrder();

  /// @notice Thrown when the protocol fee exceeds the maximum allowed
  error ProtocolFeeTooHigh();

  /// @notice Thrown when pool deployer is already set
  error PoolDeployerAlreadySet();

  /// @notice Thrown when pool deployer is not set
  error PoolDeployerNotSet();

  /// @notice Thrown when provided pool creation code hash does not match configured hash
  error InvalidPoolCreationCodeHash();

  // ============ Constants ============

  /// @notice Maximum protocol fee allowed (50%)
  uint24 public constant MAX_PROTOCOL_FEE = 500_000;

  // ============ State Variables ============

  /// @notice The pool deployer contract
  MetricOmmPoolDeployer public poolDeployer;

  /// @notice Expected keccak256 hash of MetricOmmPool creation code
  bytes32 public immutable poolCreationCodeHash;

  /// @notice Default protocol fee for new pools
  uint24 public protocolFee;

  // ============ Constructor ============

  /// @notice Creates the factory with the given owner and default protocol fee
  /// @param initialOwner The initial owner of the factory
  /// @param initialprotocolFee The initial default protocol fee
  /// @param _poolCreationCodeHash Expected keccak256 hash of MetricOmmPool creation code
  constructor(address initialOwner, uint24 initialprotocolFee, bytes32 _poolCreationCodeHash) Ownable(initialOwner) {
    if (initialprotocolFee > MAX_PROTOCOL_FEE) revert ProtocolFeeTooHigh();
    protocolFee = initialprotocolFee;
    poolCreationCodeHash = _poolCreationCodeHash;
  }

  // ============ External Functions ============

  /// @notice Sets the pool deployer contract (can only be called once by owner)
  /// @param _poolDeployer The pool deployer contract address
  function setPoolDeployer(MetricOmmPoolDeployer _poolDeployer) external onlyOwner {
    if (address(poolDeployer) != address(0)) revert PoolDeployerAlreadySet();
    poolDeployer = _poolDeployer;
    emit PoolDeployerSet(address(_poolDeployer));
  }

  /// @notice Creates a new pool with the given parameters
  /// @param params The pool creation parameters
  /// @return pool The address of the newly created pool
  function createPool(PoolParameters calldata params) external returns (address pool) {
    if (address(poolDeployer) == address(0)) revert PoolDeployerNotSet();
    if (keccak256(params.poolCreationCode) != poolCreationCodeHash) revert InvalidPoolCreationCodeHash();

    // Use default protocol fee if not specified (0 means use default)

    bytes32 poolKey = keccak256(
      abi.encode(
        params.token0,
        params.token1,
        params.priceProvider,
        params.initialToken0DensityPerLiquidityE18,
        params.initialToken1DensityPerLiquidityE18,
        params.minimalMintableLiquidity,
        params.reportSwapToPriceProvider,
        params.maxDriftE8,
        params.driftDecayPerSecondE8,
        protocolFee,
        params.adminFee,
        params.curBinDistFromProvidedPriceE6,
        keccak256(abi.encode(params.nonNegativeBinDataArray)),
        keccak256(abi.encode(params.negativeBinDataArray)),
        params.salt
      )
    );

    bytes memory constructorArgs = abi.encode(
      address(this),
      params.admin,
      params.token0,
      params.token1,
      params.priceProvider,
      params.initialToken0DensityPerLiquidityE18,
      params.initialToken1DensityPerLiquidityE18,
      params.minimalMintableLiquidity,
      params.reportSwapToPriceProvider,
      params.maxDriftE8,
      params.driftDecayPerSecondE8,
      protocolFee,
      params.adminFee,
      params.adminFeeDestination,
      params.curBinDistFromProvidedPriceE6,
      params.nonNegativeBinDataArray,
      params.negativeBinDataArray
    );

    bytes memory initCode = bytes.concat(params.poolCreationCode, constructorArgs);

    pool = poolDeployer.deploy(poolKey, initCode);

    emit PoolCreated(params.token0, params.token1, params.priceProvider, pool, poolKey);
  }

  /// @notice Sets the default protocol fee for new pools
  /// @dev Only callable by owner
  /// @param newFee The new default protocol fee
  function setprotocolFee(uint24 newFee) external onlyOwner {
    if (newFee > MAX_PROTOCOL_FEE) revert ProtocolFeeTooHigh();
    uint24 oldFee = protocolFee;
    protocolFee = newFee;
    emit protocolFeeUpdated(oldFee, newFee);
  }

  /// @notice Collects ERC20 tokens from the factory
  /// @dev Only callable by owner
  /// @param token The token to collect
  /// @param to The address to send the tokens to
  /// @param amount The amount of tokens to collect (0 = all)
  function collectTokens(address token, address to, uint256 amount) external onlyOwner {
    uint256 balance = IERC20(token).balanceOf(address(this));
    uint256 amountToCollect = amount == 0 ? balance : amount;
    if (amountToCollect > 0) {
      IERC20(token).safeTransfer(to, amountToCollect);
      emit TokensCollected(token, to, amountToCollect);
    }
  }

  /// @notice Collects ETH from the factory
  /// @dev Only callable by owner
  /// @param to The address to send the ETH to
  /// @param amount The amount of ETH to collect (0 = all)
  function collectETH(address payable to, uint256 amount) external onlyOwner {
    uint256 balance = address(this).balance;
    uint256 amountToCollect = amount == 0 ? balance : amount;
    if (amountToCollect > 0) {
      (bool success,) = to.call{value: amountToCollect}("");
      require(success, "ETH transfer failed");
      emit TokensCollected(address(0), to, amountToCollect);
    }
  }

  /// @notice Allows the factory to receive ETH
  receive() external payable {}
}

